/* Banco de perguntas: Mecânica dos Fluidos. Mesmos campos do banco de Eletrostática. */
window.BANKS=window.BANKS||{};
window.BANKS.fluidos=[{"id": "f001", "an": "oco_navio", "t": "de", "q": "Qual é a diferença entre massa específica e densidade?", "o": ["A massa específica é uma propriedade da substância; a densidade é calculada para o corpo inteiro, que pode ser oco ou de vários materiais.", "Não há nenhuma diferença: são sempre iguais.", "A massa específica mede o peso, e a densidade mede o volume.", "A densidade só vale para gases, e a massa específica só para sólidos."], "a": 0, "h": "Pense em uma bola de ferro maciça e em outra oca.", "e": "A massa específica (μ = m/V) é característica do material. A densidade (d = m/V) é a razão entre a massa e o volume do corpo todo; ela só coincide com a massa específica se o corpo for maciço e homogêneo.", "x": {"1": "Elas diferem: a densidade considera o corpo todo, incluindo partes ocas ou outros materiais.", "2": "Nenhuma das duas mede peso ou volume. As duas são massa dividida por volume.", "3": "As duas se aplicam a sólidos, líquidos e gases."}, "n": 2}, {"id": "f002", "an": "oco_navio", "t": "de", "q": "Verdadeiro ou falso: um objeto de ferro oco pode ter densidade menor que a massa específica do ferro.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "O volume do objeto inclui a parte vazia.", "e": "A cavidade aumenta o volume sem aumentar a massa. Por isso a densidade do corpo fica menor que a massa específica do ferro.", "v": 1, "x": {"1": "Um objeto oco tem massa menor para o mesmo volume, então sua densidade é menor que a do ferro maciço. A afirmação é verdadeira."}, "n": 1}, {"id": "f003", "an": "unid_dens", "t": "de", "q": "Qual é a unidade de massa específica no Sistema Internacional?", "o": ["kg/m³", "kg·m³", "N/m²", "g/s"], "a": 0, "h": "Massa dividida por volume.", "e": "Como μ = m/V, a unidade no SI é quilograma por metro cúbico (kg/m³).", "x": {"1": "kg·m³ é um produto. A unidade é massa dividida por volume: kg/m³.", "2": "N/m² é a unidade de pressão.", "3": "g/s mede vazão de massa."}, "n": 1}, {"id": "f004", "an": "oco_navio", "t": "de", "q": "Por que um navio de aço, feito de um material muito mais denso que a água, flutua?", "o": ["Porque o navio, com seu interior cheio de ar, tem densidade média menor que a da água.", "Porque o aço flutua na água.", "Porque o navio não tem peso.", "Porque a água do mar é mais densa que o aço."], "a": 0, "h": "Considere o navio inteiro, e não só o aço do casco.", "e": "O casco é oco. A densidade do conjunto (aço mais ar) é menor que a da água, e por isso o navio flutua.", "x": {"1": "O aço afunda sozinho. O navio flutua pela forma e pelo ar interno.", "2": "O navio tem peso. O empuxo é que o equilibra.", "3": "A água é menos densa que o aço. O que importa é a densidade média do navio."}, "n": 2}, {"id": "f005", "an": "mesmo_vol", "t": "de", "q": "Dois blocos têm o mesmo volume: um de madeira e outro de chumbo. Qual tem maior massa?", "o": ["O de chumbo, porque o chumbo tem maior massa específica.", "O de madeira, porque é mais leve.", "Os dois têm a mesma massa.", "Depende apenas da cor."], "a": 0, "h": "Use m = μ·V com o mesmo V.", "e": "Com volumes iguais, quem tem maior massa específica tem maior massa. O chumbo é bem mais denso que a madeira.", "x": {"1": "Mesmo volume: ganha em massa quem tem maior massa específica, e o chumbo é mais denso.", "2": "As massas são diferentes porque os materiais têm densidades diferentes.", "3": "A cor não influi na massa."}, "n": 2}, {"id": "f006", "an": "unid_dens", "t": "de", "q": "Verdadeiro ou falso: 1 g/cm³ equivale a 1000 kg/m³.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Converta gramas em quilogramas e centímetros cúbicos em metros cúbicos.", "e": "1 g = 10⁻³ kg e 1 cm³ = 10⁻⁶ m³. Assim, 1 g/cm³ = 10⁻³ / 10⁻⁶ kg/m³ = 1000 kg/m³.", "v": 1, "x": {"1": "1 g/cm³ = 10⁻³ kg / 10⁻⁶ m³ = 1000 kg/m³. A afirmação é verdadeira."}, "n": 1}, {"id": "f007", "an": "meia_barra", "t": "de", "q": "Uma barra de alumínio maciça é cortada ao meio. A massa específica de cada metade, em comparação com a da barra inteira:", "o": ["É a mesma.", "É a metade.", "É o dobro.", "É nula."], "a": 0, "h": "A massa específica é característica do material.", "e": "Massa e volume caem pela metade, mas a razão m/V continua igual. A massa específica é propriedade do material.", "x": {"1": "Cortar ao meio divide massa e volume igualmente. A razão não muda.", "2": "A razão não dobra, porque massa e volume caem pela metade.", "3": "A massa específica não vira zero: o material continua o mesmo."}, "n": 2}, {"id": "f008", "an": "oleo_agua", "t": "de", "q": "Por que o óleo de cozinha fica por cima da água quando os dois se misturam?", "o": ["Porque o óleo é menos denso que a água.", "Porque o óleo é mais denso que a água.", "Porque o óleo não tem massa.", "Porque a água é mais leve que o ar."], "a": 0, "h": "Compare as massas específicas das duas substâncias.", "e": "O óleo tem massa específica menor que a da água (cerca de 0,9 g/cm³). Por isso ele fica por cima.", "x": {"1": "O que fica por cima é o menos denso. O óleo flutua.", "2": "O óleo tem massa e é menos denso que a água.", "3": "A água é mais pesada que o ar, mas isso não explica o óleo."}, "n": 2}, {"id": "f009", "an": "afunda_flutua", "t": "de", "q": "Ao colocar os materiais abaixo em um balde com água (1,0 g/cm³), qual deles afunda?", "o": ["Ferro (7,8 g/cm³).", "Gelo (0,92 g/cm³).", "Madeira (0,6 g/cm³).", "Cortiça (0,2 g/cm³)."], "a": 0, "h": "Afunda o que é mais denso que a água.", "e": "Só o ferro tem massa específica maior que a da água, então só ele afunda.", "x": {"1": "O gelo (0,92 g/cm³) é menos denso que a água e flutua.", "2": "A madeira (0,6) é menos densa e flutua.", "3": "A cortiça (0,2) é muito menos densa e flutua."}, "n": 2}, {"id": "f010", "an": "calc_f010", "t": "de", "q": "Um bloco de 500 g ocupa um volume de 250 cm³. Qual é a massa específica do material?", "o": ["2 g/cm³", "0,5 g/cm³", "125 g/cm³", "0,002 g/cm³"], "a": 0, "h": "Use μ = m / V.", "e": "μ = 500 g / 250 cm³ = 2 g/cm³.", "c": 1, "x": {"1": "0,5 g/cm³ inverteu a divisão: o certo é 500/250.", "2": "125 g/cm³ multiplicou em vez de dividir.", "3": "0,002 g/cm³ calculou 1/500, ignorando a massa."}, "n": 1}, {"id": "f011", "an": "calc_f011", "t": "de", "q": "Qual é a massa de 2 m³ de água, sabendo que a massa específica da água é 1000 kg/m³?", "o": ["2000 kg", "500 kg", "2 kg", "20 kg"], "a": 0, "h": "Use m = μ·V.", "e": "m = 1000 kg/m³ × 2 m³ = 2000 kg.", "c": 1, "x": {"1": "500 kg dividiu em vez de multiplicar: m = 1000 · 2.", "2": "2 kg ignora o fator 1000.", "3": "20 kg está errado: m = ρ·V = 1000 · 2."}, "n": 1}, {"id": "f012", "t": "pr", "q": "A pressão exercida por uma força sobre uma superfície é definida como:", "o": ["A força perpendicular à superfície dividida pela área.", "A força multiplicada pela área.", "A massa dividida pelo volume.", "A área dividida pela força."], "a": 0, "h": "Pressão é força por unidade de área.", "e": "p = F / A, em que F é a componente da força perpendicular à superfície.", "f": "pressao_area", "x": {"1": "Pressão é força dividida por área, não multiplicada.", "2": "Massa dividida por volume é a densidade.", "3": "A divisão está invertida: o certo é força sobre área."}, "an": "pressao_area", "n": 1}, {"id": "f013", "an": "pa_unid", "t": "pr", "q": "Qual é a unidade de pressão no Sistema Internacional?", "o": ["Pascal (Pa), igual a 1 N/m².", "Newton (N).", "Joule (J).", "Watt (W)."], "a": 0, "h": "Pressão é força por área.", "e": "A unidade é o pascal: 1 Pa = 1 N/m².", "x": {"1": "Newton é unidade de força.", "2": "Joule é unidade de energia.", "3": "Watt é unidade de potência."}, "n": 1}, {"id": "f014", "an": "faca_area", "t": "pr", "q": "Por que uma faca bem afiada corta melhor que uma sem fio, aplicando a mesma força?", "o": ["Porque a área de contato é menor e a pressão, maior.", "Porque a faca afiada pesa mais.", "Porque a faca afiada tem mais massa específica.", "Porque a pressão não depende da área."], "a": 0, "h": "Na fórmula p = F / A, o que acontece se A diminui?", "e": "Com a mesma força, uma área menor produz uma pressão maior, e a faca penetra mais facilmente.", "x": {"1": "O peso da faca não é o que muda.", "2": "A massa específica do material não explica o corte.", "3": "A pressão depende da área, e por isso a faca afiada corta melhor."}, "n": 1}, {"id": "f015", "t": "pr", "q": "Verdadeiro ou falso: aumentando a área de apoio e mantendo a mesma força, a pressão aumenta.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Observe a área no denominador de p = F / A.", "e": "A área está no denominador. Com a mesma força, uma área maior leva a uma pressão menor.", "v": 1, "x": {"0": "Com a mesma força, aumentar a área diminui a pressão (p = F / A). A afirmação é falsa."}, "an": "pressao_area", "n": 1}, {"id": "f016", "an": "raquete", "t": "pr", "q": "Por que as raquetes de neve ajudam a pessoa a não afundar?", "o": ["Porque aumentam a área de apoio e diminuem a pressão sobre a neve.", "Porque diminuem o peso da pessoa.", "Porque aumentam a pressão sobre a neve.", "Porque a neve fica mais dura com o calor."], "a": 0, "h": "O peso é o mesmo; o que muda é a área.", "e": "O peso da pessoa é o mesmo, mas ele se distribui por uma área maior. Com isso, a pressão sobre a neve diminui.", "x": {"1": "O peso da pessoa continua o mesmo.", "2": "Aumentam a área, e a pressão diminui.", "3": "O calor não é o fator aqui."}, "n": 1}, {"id": "f017", "an": "pressao_dir", "t": "pr", "q": "Verdadeiro ou falso: a pressão é uma grandeza vetorial.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Ela tem direção e sentido?", "e": "A pressão é uma grandeza escalar. A força é que é vetorial; só sua componente perpendicular entra no cálculo.", "v": 1, "x": {"0": "A pressão é uma grandeza escalar. Ela atua em todas as direções, sem direção própria. A afirmação é falsa."}, "n": 1}, {"id": "f018", "an": "faca_area", "t": "pr", "q": "Por que os pregos têm a ponta fina?", "o": ["Para que a força se concentre em uma área pequena e a pressão seja grande.", "Para diminuir a pressão sobre a madeira.", "Para que o prego fique mais leve.", "Para que a pressão seja igual em todos os pontos."], "a": 0, "h": "Pense na área de contato da ponta.", "e": "A ponta tem área muito pequena. Com isso, a pressão sobre a madeira é muito alta, e o prego entra mais fácil.", "x": {"1": "A ponta fina aumenta a pressão, que é o que se quer.", "2": "O peso do prego não é o motivo.", "3": "A pressão é bem maior na ponta, não igual em todos os pontos."}, "n": 1}, {"id": "f019", "t": "pr", "q": "Em um líquido em repouso, a pressão aumenta com:", "o": ["A profundidade.", "A altura acima da superfície.", "A cor do líquido.", "A temperatura ambiente apenas."], "a": 0, "h": "É o teorema de Stevin: p = p₀ + μ·g·h.", "e": "Quanto mais fundo, maior o peso da coluna de líquido acima, e maior é a pressão.", "f": "hidro", "x": {"1": "A altura acima da superfície não vale: a pressão cresce para baixo.", "2": "A cor não influencia.", "3": "A temperatura influi pouco. O fator principal é a profundidade."}, "an": "profund", "n": 1}, {"id": "f020", "an": "calc_f020", "t": "pr", "q": "Uma força de 200 N age perpendicularmente sobre uma área de 0,5 m². Qual é a pressão?", "o": ["400 Pa", "100 Pa", "40 Pa", "0,0025 Pa"], "a": 0, "h": "Use p = F / A.", "e": "p = 200 N / 0,5 m² = 400 Pa.", "c": 1, "x": {"1": "100 Pa dividiu por 2 em vez de dividir por 0,5.", "2": "40 Pa está dez vezes menor.", "3": "0,0025 Pa inverteu a divisão."}, "n": 1}, {"id": "f021", "an": "calc_f021", "t": "pr", "q": "Uma caixa de peso 60 N está apoiada sobre uma face de 0,3 m². Qual é a pressão que ela exerce no piso?", "o": ["200 Pa", "18 Pa", "20 Pa", "180 Pa"], "a": 0, "h": "Aqui a força é o peso da caixa.", "e": "p = 60 N / 0,3 m² = 200 Pa.", "c": 1, "x": {"1": "18 Pa multiplicou 60 por 0,3.", "2": "20 Pa erra uma casa decimal.", "3": "180 Pa não vem de F / A."}, "n": 1}, {"id": "f022", "an": "calc_f022", "t": "pr", "q": "Qual é a pressão exercida por uma coluna de água de 5 m de altura (μ = 1000 kg/m³ e g = 10 m/s²), sem contar a pressão atmosférica?", "o": ["5 × 10⁴ Pa", "5 × 10³ Pa", "2 × 10⁻³ Pa", "5 × 10⁵ Pa"], "a": 0, "h": "Use p = μ·g·h.", "e": "p = 1000 × 10 × 5 = 5 × 10⁴ Pa.", "c": 1, "x": {"1": "5 × 10³ está uma ordem de grandeza menor: p = 1000·10·5.", "2": "2 × 10⁻³ Pa é o inverso do valor.", "3": "5 × 10⁵ Pa está dez vezes maior."}, "n": 2}, {"id": "f023", "an": "atm_peso", "t": "pa", "q": "A pressão atmosférica existe porque:", "o": ["O ar tem peso e a camada de ar sobre nós exerce pressão.", "O ar não tem massa.", "A Terra gira.", "O vento sopra sempre para baixo."], "a": 0, "h": "Pense na camada de ar acima de você.", "e": "O ar tem massa, e a Terra o atrai. O peso da coluna de ar acima de nós gera a pressão atmosférica.", "x": {"1": "O ar tem massa e peso, por isso exerce pressão.", "2": "A rotação da Terra não é a origem dessa pressão.", "3": "O vento não explica a pressão atmosférica."}, "n": 1}, {"id": "f024", "t": "pa", "q": "Ao subir uma montanha, a pressão atmosférica:", "o": ["Diminui.", "Aumenta.", "Fica constante.", "Fica sempre nula."], "a": 0, "h": "Compare a quantidade de ar acima de você em baixo e no alto.", "e": "Quanto mais alto, menos ar há acima, e menor é a pressão atmosférica.", "x": {"1": "A pressão diminui com a altitude, porque há menos ar acima.", "2": "Ela varia com a altitude.", "3": "A pressão diminui, mas não chega a zero em montanhas."}, "an": "atmosfera", "n": 1}, {"id": "f025", "an": "atm_peso", "t": "pa", "q": "Verdadeiro ou falso: ao nível do mar, a pressão atmosférica vale aproximadamente 1,0 × 10⁵ Pa (1 atm).", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "É a pressão normal que usamos como referência.", "e": "O valor normal é 1 atm, que corresponde a cerca de 1,0 × 10⁵ Pa.", "v": 1, "x": {"1": "Ao nível do mar, 1 atm ≈ 1,0 × 10⁵ Pa. A afirmação é verdadeira."}, "n": 1}, {"id": "f026", "t": "pa", "q": "Por que é possível beber um refresco usando um canudo?", "o": ["Ao sugar, a pressão dentro do canudo diminui e a pressão atmosférica empurra o líquido para cima.", "Porque o líquido é puxado pela boca, sem influência do ar.", "Porque o canudo é mais leve que o líquido.", "Porque o líquido sobe sozinho por ser denso."], "a": 0, "h": "Pense na diferença de pressão entre a boca e a superfície do líquido.", "e": "Ao sugar, reduzimos a pressão no canudo. A pressão atmosférica sobre a superfície do líquido é maior e o empurra pelo canudo.", "x": {"1": "O ar tem papel essencial: a pressão atmosférica empurra o líquido.", "2": "O canudo ser leve não faz o líquido subir.", "3": "O líquido não sobe sozinho; é a pressão externa que o empurra."}, "an": "canudo", "n": 2}, {"id": "f027", "an": "ouvido", "t": "pa", "q": "Por que os ouvidos “estalam” quando um carro sobe ou desce uma serra?", "o": ["Porque a pressão do ar externo muda e o ar do ouvido médio se ajusta a essa diferença.", "Porque a temperatura do ar muda.", "Porque a massa específica do corpo muda.", "Porque o som viaja mais rápido na serra."], "a": 0, "h": "Pense na pressão atmosférica em alturas diferentes.", "e": "A pressão externa varia com a altitude. O ouvido médio precisa equilibrar essa diferença, e isso produz o estalo.", "x": {"1": "A mudança de temperatura não é a causa principal.", "2": "A massa específica do corpo não muda.", "3": "A velocidade do som não explica o estalo."}, "n": 2}, {"id": "f028", "an": "pressao_dir", "t": "pa", "q": "Verdadeiro ou falso: a pressão atmosférica atua apenas de cima para baixo.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Pense em um balão de gás cheio.", "e": "Como o ar é um fluido, a pressão atua em todas as direções, de cima, de baixo e dos lados.", "v": 1, "x": {"0": "A pressão atmosférica atua em todas as direções. A afirmação é falsa."}, "n": 1}, {"id": "f029", "t": "pa", "q": "Uma ventosa gruda em um vidro liso porque:", "o": ["A pressão atmosférica externa é maior que a pressão do ar que sobrou dentro dela.", "A ventosa tem cola.", "O vidro é magnético.", "A pressão atmosférica não existe."], "a": 0, "h": "Ao apertar a ventosa, parte do ar sai.", "e": "Ao pressionar, o ar sai e a pressão interna diminui. A pressão atmosférica de fora é maior e mantém a ventosa colada.", "x": {"1": "Uma ventosa funciona sem cola.", "2": "O vidro não é magnético.", "3": "A pressão atmosférica existe e é ela que prende a ventosa."}, "an": "ventosa", "n": 2}, {"id": "f030", "an": "atmosfera", "t": "pa", "q": "Em qual lugar a pressão atmosférica é maior?", "o": ["Em uma cidade litorânea, ao nível do mar.", "No topo de uma montanha alta.", "Em um avião a 10 000 m de altitude.", "No espaço, fora da atmosfera."], "a": 0, "h": "Quanto mais baixo, mais ar acima de você.", "e": "Ao nível do mar, a coluna de ar acima é maior, e por isso a pressão é maior.", "x": {"1": "No topo da montanha há menos ar acima, então a pressão é menor.", "2": "A 10 000 m a pressão é bem menor.", "3": "No espaço a pressão é praticamente nula."}, "n": 1}, {"id": "f031", "an": "traje", "t": "pa", "q": "Por que astronautas precisam usar trajes pressurizados no espaço?", "o": ["Porque lá fora não há pressão atmosférica para equilibrar a pressão do corpo.", "Porque o espaço é muito quente.", "Porque lá a pressão atmosférica é enorme.", "Porque lá o ar é muito denso."], "a": 0, "h": "Fora da atmosfera a pressão externa é praticamente nula.", "e": "Sem o traje, a pressão interna do corpo não teria equilíbrio com o meio externo. O traje mantém uma pressão adequada.", "x": {"1": "O problema não é o calor, mas a falta de pressão.", "2": "No espaço a pressão externa é praticamente nula.", "3": "No espaço não há ar denso, e sim vácuo."}, "n": 2}, {"id": "f032", "an": "ebulicao_p", "t": "pa", "q": "A panela de pressão cozinha os alimentos mais depressa porque:", "o": ["Com a pressão maior, a água ferve a uma temperatura mais alta.", "A água fica sem peso.", "A pressão diminui dentro da panela.", "O alimento fica mais leve."], "a": 0, "h": "Pressão e ponto de ebulição estão ligados.", "e": "Dentro da panela, a pressão é maior que a atmosférica e a água só ferve a uma temperatura mais alta, o que acelera o cozimento.", "x": {"1": "A água continua com peso.", "2": "A pressão aumenta dentro da panela.", "3": "O alimento não muda de peso."}, "n": 2}, {"id": "f033", "an": "torr_exp", "t": "to", "q": "No experimento de Torricelli, o que se usa para medir a pressão atmosférica?", "o": ["Um tubo de vidro cheio de mercúrio, emborcado em uma cuba com mercúrio.", "Uma balança de dois pratos.", "Um tubo vazio mergulhado na água.", "Uma mola presa ao teto."], "a": 0, "h": "O líquido usado é muito denso.", "e": "O tubo fechado em uma ponta e cheio de mercúrio é virado em uma cuba com mercúrio. A coluna desce e para em uma altura que depende da pressão atmosférica.", "f": "torricelli", "x": {"1": "Uma balança de pratos não mede a pressão atmosférica.", "2": "Um tubo vazio na água não reproduz o experimento. É preciso mercúrio e um tubo cheio.", "3": "Uma mola no teto não faz parte do experimento."}, "n": 1}, {"id": "f034", "an": "torr_76", "t": "to", "q": "Ao nível do mar, a altura da coluna de mercúrio no experimento de Torricelli é de aproximadamente:", "o": ["76 cm.", "10 m.", "1 cm.", "760 m."], "a": 0, "h": "É o valor que define 1 atm em mmHg.", "e": "Ao nível do mar, a coluna tem cerca de 76 cm (760 mm) de mercúrio.", "f": "torricelli", "x": {"1": "10 m seria a altura com água.", "2": "1 cm é muito pouco.", "3": "760 m confunde 760 mm com metros."}, "n": 1}, {"id": "f035", "an": "torr_exp", "t": "to", "q": "O que existe no espaço acima do mercúrio, no topo do tubo de Torricelli?", "o": ["Praticamente vácuo.", "Ar com pressão de 1 atm.", "Água.", "Mercúrio líquido comprimido."], "a": 0, "h": "O mercúrio desceu e deixou um espaço.", "e": "Quando o mercúrio desce, o espaço no topo fica praticamente vazio. É o chamado vácuo de Torricelli.", "f": "torricelli", "x": {"1": "Se houvesse ar com 1 atm, a coluna não se manteria.", "2": "Dentro do tubo só há mercúrio.", "3": "O mercúrio líquido não ocupa esse espaço."}, "n": 1}, {"id": "f036", "t": "to", "q": "Verdadeiro ou falso: inclinar o tubo no experimento de Torricelli muda a altura vertical da coluna de mercúrio.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "A pressão depende da altura vertical.", "e": "A altura vertical é determinada pela pressão atmosférica e não muda. O comprimento do mercúrio no tubo é que aumenta, mas a altura vertical é a mesma.", "v": 1, "x": {"0": "A altura vertical da coluna depende só da pressão, não da inclinação. A afirmação é falsa."}, "an": "torr_incl", "n": 1}, {"id": "f037", "t": "to", "q": "Se o experimento de Torricelli for feito no alto de uma montanha, a coluna de mercúrio:", "o": ["Fica menor que 76 cm.", "Fica maior que 76 cm.", "Continua exatamente com 76 cm.", "Desaparece."], "a": 0, "h": "A pressão atmosférica diminui com a altitude.", "e": "No alto da montanha, a pressão atmosférica é menor e sustenta uma coluna menor de mercúrio.", "x": {"1": "Mais alto, a pressão é menor, então a coluna é menor.", "2": "A coluna só seria 76 cm ao nível do mar.", "3": "A coluna diminui, mas não desaparece."}, "an": "torr_alt", "n": 2}, {"id": "f038", "an": "torr_agua", "t": "to", "q": "Por que Torricelli usou mercúrio em vez de água?", "o": ["Porque o mercúrio é muito mais denso, e a coluna fica pequena e fácil de manusear.", "Porque o mercúrio é mais leve que a água.", "Porque a água evapora no experimento sem outro motivo.", "Porque o mercúrio não tem massa."], "a": 0, "h": "Compare as massas específicas dos dois líquidos.", "e": "O mercúrio é cerca de 13,6 vezes mais denso que a água. Com água, a coluna teria cerca de 10 m, e com mercúrio tem 76 cm.", "x": {"1": "O mercúrio é mais denso, não mais leve.", "2": "A evaporação não é o ponto principal: a questão é a altura da coluna.", "3": "O mercúrio tem massa e densidade alta."}, "n": 2}, {"id": "f039", "an": "torr_76", "t": "to", "q": "A pressão de 1 atm equivale a:", "o": ["760 mmHg.", "76 mmHg.", "7600 mmHg.", "1 mmHg."], "a": 0, "h": "Relacione com a altura da coluna de mercúrio.", "e": "A coluna de 760 mm de mercúrio equilibra a pressão atmosférica normal, então 1 atm = 760 mmHg.", "x": {"1": "76 mmHg é a altura em cm.", "2": "7600 mmHg está dez vezes maior.", "3": "1 mmHg é a unidade, não a pressão de 1 atm."}, "n": 1}, {"id": "f040", "an": "torr_76", "t": "to", "q": "Verdadeiro ou falso: no experimento de Torricelli, a pressão exercida pela coluna de mercúrio equilibra a pressão atmosférica.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "É o equilíbrio que mantém a coluna parada.", "e": "A pressão da coluna (μ·g·h) é igual à pressão atmosférica que atua na superfície do mercúrio da cuba.", "v": 1, "f": "torricelli", "x": {"1": "A coluna de mercúrio equilibra a pressão atmosférica. A afirmação é verdadeira."}, "n": 1}, {"id": "f041", "t": "to", "q": "Se um tubo de Torricelli mais largo for usado, a altura da coluna de mercúrio:", "o": ["Continua a mesma.", "Aumenta.", "Diminui.", "Passa a ser nula."], "a": 0, "h": "A pressão não depende da largura do tubo.", "e": "A altura depende da pressão atmosférica e da massa específica do líquido, e não da largura ou da forma do tubo.", "x": {"1": "A largura do tubo não altera a altura.", "2": "A altura não diminui com um tubo mais largo.", "3": "A coluna continua a existir."}, "an": "torr_larg", "n": 2}, {"id": "f042", "an": "torr_agua", "t": "to", "q": "Se o experimento de Torricelli fosse feito com água, qual seria, aproximadamente, a altura da coluna ao nível do mar? (p = 1,0 × 10⁵ Pa, μ = 1000 kg/m³, g = 10 m/s²)", "o": ["10 m", "0,76 m", "1 m", "100 m"], "a": 0, "h": "Use p = μ·g·h e isole h.", "e": "h = p / (μ·g) = 10⁵ / (1000 × 10) = 10 m.", "c": 1, "x": {"1": "0,76 m é a altura de mercúrio em metros.", "2": "1 m erra a conta: h = p / (ρg) = 10⁵/(1000·10).", "3": "100 m erra por um fator de 10."}, "n": 3}, {"id": "f043", "an": "torr_exp", "t": "cs", "q": "Quem é o cientista desenhado na figura, que realizou o experimento do barômetro de mercúrio?", "o": ["Evangelista Torricelli", "Blaise Pascal", "Arquimedes", "Simon Stevin"], "a": 0, "h": "Ele viveu na Itália, no século XVII, e foi discípulo de Galileu.", "e": "Evangelista Torricelli (1608–1647), físico italiano, realizou em 1643 o experimento que mostrou a existência da pressão atmosférica e inventou o barômetro de mercúrio.", "f": "ret_torricelli", "x": {"1": "Pascal estudou a pressão nos fluidos, mas não fez o barômetro de mercúrio.", "2": "Arquimedes viveu muito antes.", "3": "Stevin estudou a hidrostática, não o barômetro."}, "n": 1}, {"id": "f044", "an": "pa_unid", "t": "cs", "q": "Quem é o cientista desenhado na figura, que dá nome à unidade de pressão do SI?", "o": ["Blaise Pascal", "Evangelista Torricelli", "Arquimedes", "Simon Stevin"], "a": 0, "h": "A unidade de pressão no SI é o pascal.", "e": "Blaise Pascal (1623–1662), francês, estudou a pressão nos fluidos. A unidade de pressão do SI recebeu o nome dele.", "f": "ret_pascal", "x": {"1": "Torricelli tem uma unidade (torr), mas não a do SI.", "2": "Arquimedes não dá nome a essa unidade.", "3": "Stevin não dá nome à unidade de pressão."}, "n": 1}, {"id": "f045", "an": "empuxo", "t": "cs", "q": "Quem é o cientista desenhado na figura, famoso pelo princípio do empuxo e pela história da coroa do rei?", "o": ["Arquimedes", "Blaise Pascal", "Evangelista Torricelli", "Simon Stevin"], "a": 0, "h": "Viveu em Siracusa, na Grécia antiga.", "e": "Arquimedes (cerca de 287–212 a.C.) formulou o princípio do empuxo: um corpo mergulhado em um fluido recebe uma força para cima igual ao peso do fluido deslocado.", "f": "ret_arquimedes", "x": {"1": "Pascal estudou pressão, não o empuxo.", "2": "Torricelli inventou o barômetro.", "3": "Stevin estudou a pressão hidrostática."}, "n": 1}, {"id": "f046", "an": "profund", "t": "cs", "q": "Quem é o cientista desenhado na figura, que mostrou que a pressão em um líquido aumenta com a profundidade (teorema fundamental da hidrostática)?", "o": ["Simon Stevin", "Blaise Pascal", "Arquimedes", "Evangelista Torricelli"], "a": 0, "h": "O teorema fundamental da hidrostática leva o nome dele.", "e": "Simon Stevin (1548–1620), flamengo, estudou a pressão nos líquidos. O teorema de Stevin diz que a pressão aumenta com a profundidade: p = p₀ + μ·g·h.", "f": "ret_stevin", "x": {"1": "Pascal estudou a transmissão da pressão.", "2": "Arquimedes estudou o empuxo.", "3": "Torricelli inventou o barômetro."}, "n": 1}, {"id": "f047", "an": "torr_alt", "t": "cs", "q": "Verdadeiro ou falso: Pascal pediu que o experimento de Torricelli fosse repetido em uma montanha, e a coluna de mercúrio ficou menor lá em cima.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "A pressão atmosférica diminui com a altitude.", "e": "Em 1648, a pedido de Pascal, o experimento foi repetido na montanha Puy de Dôme, e a coluna ficou menor. Isso confirmou que a pressão atmosférica diminui com a altitude.", "v": 1, "x": {"1": "Pascal sugeriu a repetição em uma montanha, e a coluna foi menor. A afirmação é verdadeira."}, "n": 1}, {"id": "f048", "t": "em", "q": "O princípio de Arquimedes afirma que um corpo mergulhado em um fluido recebe uma força para cima cujo valor é igual:", "o": ["Ao peso do fluido que o corpo desloca.", "Ao peso do próprio corpo.", "À massa do corpo multiplicada pela área.", "À pressão atmosférica local."], "a": 0, "h": "Pense no fluido que sai do lugar quando o corpo entra.", "e": "O empuxo tem o mesmo valor do peso do volume de fluido deslocado pelo corpo.", "f": "empuxo", "x": {"1": "O empuxo não é igual ao peso do corpo, exceto quando o corpo flutua em equilíbrio.", "2": "A massa vezes a área não é uma grandeza do princípio.", "3": "A pressão atmosférica não define o empuxo."}, "an": "empuxo", "n": 1}, {"id": "f049", "t": "em", "q": "Qual é a direção e o sentido do empuxo?", "o": ["Vertical, para cima.", "Vertical, para baixo.", "Horizontal, para a direita.", "Sempre na direção do movimento do corpo."], "a": 0, "h": "É a força que ajuda o corpo a boiar.", "e": "O empuxo é vertical e aponta para cima, contrário ao peso.", "f": "empuxo", "x": {"1": "O empuxo aponta para cima, contra o peso.", "2": "Ele não é horizontal.", "3": "Ele não segue o movimento do corpo."}, "an": "empuxo", "n": 1}, {"id": "f050", "t": "em", "q": "Verdadeiro ou falso: o empuxo depende da massa específica do fluido e do volume do corpo que está imerso.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Use E = μ do fluido · g · volume imerso.", "e": "E = μf·g·Vi. Quanto mais denso o fluido e maior o volume imerso, maior é o empuxo.", "v": 1, "x": {"1": "E = ρ·V·g, então depende da densidade do fluido e do volume imerso. A afirmação é verdadeira."}, "an": "empuxo", "n": 1}, {"id": "f051", "an": "afunda_flutua", "t": "em", "q": "Um corpo maciço afunda em um líquido quando:", "o": ["Sua densidade é maior que a do líquido.", "Sua densidade é menor que a do líquido.", "Seu volume é muito grande.", "O líquido é muito frio."], "a": 0, "h": "Compare o peso com o empuxo máximo.", "e": "Se a densidade do corpo é maior que a do líquido, o peso supera o empuxo máximo e o corpo afunda.", "x": {"1": "Com densidade menor, o corpo flutuaria.", "2": "O volume grande não decide: a densidade é que decide.", "3": "A temperatura do líquido não é o critério."}, "n": 1}, {"id": "f052", "an": "barco_eq", "t": "em", "q": "Um barco flutua em equilíbrio, parcialmente imerso. Nessa situação:", "o": ["O empuxo tem o mesmo valor do peso do barco.", "O empuxo é maior que o peso.", "O empuxo é nulo.", "O peso do barco é nulo."], "a": 0, "h": "Em equilíbrio, a força resultante é nula.", "e": "Para o barco ficar parado na vertical, o empuxo e o peso têm o mesmo valor e sentidos opostos.", "f": "empuxo", "x": {"1": "Se o empuxo fosse maior, o barco subiria.", "2": "O empuxo não é nulo: ele sustenta o barco.", "3": "O barco tem peso."}, "n": 3}, {"id": "f053", "an": "piscina", "t": "em", "q": "Por que uma pessoa se sente mais leve dentro de uma piscina?", "o": ["Porque a água exerce sobre ela uma força para cima, o empuxo.", "Porque a massa da pessoa diminui.", "Porque a gravidade é menor na água.", "Porque a pressão atmosférica some."], "a": 0, "h": "O peso real não muda, mas há outra força agindo.", "e": "A massa e o peso continuam os mesmos. O empuxo equilibra parte do peso, e por isso o corpo parece mais leve.", "x": {"1": "Sua massa não muda na água.", "2": "A gravidade é a mesma.", "3": "A pressão atmosférica não some."}, "n": 2}, {"id": "f054", "t": "em", "q": "Verdadeiro ou falso: dois objetos de mesmo volume, totalmente imersos na água, sofrem o mesmo empuxo, mesmo que tenham massas diferentes.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "O empuxo depende do volume deslocado, não da massa do corpo.", "e": "O volume de água deslocado é igual nos dois casos, então o empuxo também é igual.", "v": 1, "x": {"1": "Com o mesmo volume imerso no mesmo fluido, E = ρ·V·g é igual. A massa não entra. A afirmação é verdadeira."}, "an": "empuxo", "n": 1}, {"id": "f055", "t": "em", "q": "Como um submarino consegue subir à superfície?", "o": ["Esvaziando os tanques de lastro, o que reduz seu peso médio.", "Aumentando a pressão atmosférica.", "Ligando as hélices na vertical, sem alterar nada mais.", "Aumentando a quantidade de água nos tanques."], "a": 0, "h": "Pense em como mudar a densidade média do submarino.", "e": "Ao expulsar a água dos tanques, o submarino fica menos denso e o empuxo passa a superar o peso.", "x": {"1": "A pressão atmosférica não é controlada pelo submarino.", "2": "As hélices ajudam a mover, mas a subida vem da variação do peso médio.", "3": "Encher os tanques com água aumenta o peso médio e faz o submarino descer."}, "an": "submarino", "n": 3}, {"id": "f056", "an": "mar_morto", "t": "em", "q": "Por que é mais fácil boiar no Mar Morto do que em uma piscina comum?", "o": ["Porque a água do Mar Morto é mais densa e produz mais empuxo.", "Porque a água do Mar Morto é menos densa.", "Porque lá a gravidade é maior.", "Porque lá não há pressão atmosférica."], "a": 0, "h": "Compare as massas específicas das duas águas.", "e": "A água salgada do Mar Morto é muito mais densa. Para o mesmo volume imerso, o empuxo é maior.", "x": {"1": "Se fosse menos densa, haveria menos empuxo.", "2": "A gravidade é a mesma.", "3": "Há pressão atmosférica no Mar Morto."}, "n": 3}, {"id": "f057", "an": "balao_ar", "t": "em", "q": "Verdadeiro ou falso: o empuxo também atua em corpos mergulhados em gases, como um balão no ar.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Gases também são fluidos.", "e": "O princípio de Arquimedes vale para qualquer fluido, inclusive o ar. Por isso balões cheios de gás menos denso que o ar sobem.", "v": 1, "x": {"1": "Gases também são fluidos e exercem empuxo. É por isso que um balão sobe. A afirmação é verdadeira."}, "n": 1}, {"id": "f058", "t": "em", "q": "Por que o gelo flutua na água, com a maior parte do volume submersa?", "o": ["Porque o gelo é um pouco menos denso que a água líquida.", "Porque o gelo não tem peso.", "Porque o gelo é muito mais denso que a água.", "Porque o gelo é oco."], "a": 0, "h": "A massa específica do gelo é cerca de 0,92 g/cm³.", "e": "Como a massa específica do gelo (cerca de 0,92 g/cm³) é menor que a da água, ele flutua, com cerca de 90% do volume submerso.", "x": {"1": "O gelo tem peso.", "2": "Se fosse muito mais denso, o gelo afundaria.", "3": "O gelo não precisa ser oco: ele é um pouco menos denso que a água líquida."}, "an": "flut92", "n": 3}, {"id": "f059", "t": "em", "q": "Um bloco tem peso de 50 N no ar. Mergulhado na água, uma balança indica 30 N. Qual é o valor do empuxo sobre o bloco?", "o": ["20 N", "80 N", "30 N", "50 N"], "a": 0, "h": "Peso aparente = peso real menos empuxo.", "e": "P_aparente = P − E, então E = 50 − 30 = 20 N.", "c": 1, "x": {"1": "80 N soma os dois valores. O empuxo é a diferença: 50 − 30.", "2": "30 N é a leitura da balança, o peso aparente.", "3": "50 N é o peso no ar."}, "an": "balanca", "n": 2}, {"id": "f060", "t": "em", "q": "Um bloco de 0,002 m³ está totalmente imerso na água (μ = 1000 kg/m³, g = 10 m/s²). Qual é o empuxo sobre ele?", "o": ["20 N", "2 N", "200 N", "0,2 N"], "a": 0, "h": "Use E = μ·g·V.", "e": "E = 1000 × 10 × 0,002 = 20 N.", "c": 1, "x": {"1": "2 N tem fator 10 a menos.", "2": "200 N tem fator 10 a mais.", "3": "0,2 N tem fator 100 a menos."}, "an": "empuxo", "n": 2}, {"id": "f061", "t": "em", "q": "Um corpo homogêneo flutua na água com 40% do seu volume imerso. Qual é a massa específica do corpo? (μ da água = 1000 kg/m³)", "o": ["400 kg/m³", "600 kg/m³", "1000 kg/m³", "250 kg/m³"], "a": 0, "h": "Em equilíbrio, peso = empuxo.", "e": "μc·V·g = μágua·(0,4V)·g, então μc = 0,4 × 1000 = 400 kg/m³.", "c": 1, "x": {"1": "600 kg/m³ corresponde a 60% imerso.", "2": "1000 kg/m³ é a densidade da água, e o corpo afundaria ou ficaria totalmente imerso.", "3": "250 kg/m³ não corresponde a 40% imerso."}, "an": "flut40", "n": 3}, {"id": "f062", "an": "pascal_pt", "t": "pp", "q": "O princípio de Pascal afirma que, em um líquido em equilíbrio, um acréscimo de pressão em um ponto:", "o": ["Transmite-se integralmente a todos os pontos do líquido.", "Fica apenas no ponto em que foi aplicado.", "Diminui com a distância.", "Só chega até o fundo do recipiente."], "a": 0, "h": "Pense em apertar uma seringa fechada.", "e": "O acréscimo de pressão se transmite com o mesmo valor a todos os pontos do líquido e às paredes do recipiente.", "f": "prensa", "x": {"1": "O acréscimo de pressão se transmite a todos os pontos.", "2": "Ele não diminui com a distância em um líquido em equilíbrio.", "3": "Ele chega a todos os pontos, e não apenas ao fundo."}, "n": 1}, {"id": "f063", "an": "prensa_forca", "t": "pp", "q": "Qual é a relação entre as forças e as áreas dos êmbolos de uma prensa hidráulica ideal?", "o": ["F₁ / A₁ = F₂ / A₂", "F₁ · A₁ = F₂ · A₂", "F₁ + A₁ = F₂ + A₂", "F₁ = F₂, sempre."], "a": 0, "h": "A pressão é a mesma nos dois êmbolos.", "e": "Como a pressão é transmitida integralmente, F₁ / A₁ = F₂ / A₂.", "f": "prensa", "x": {"1": "O produto da força pela área não é o mesmo. O que se mantém é a pressão: F / A.", "2": "Somar força e área não faz sentido físico.", "3": "As forças só seriam iguais se as áreas fossem iguais."}, "n": 2}, {"id": "f064", "an": "prensa_forca", "t": "pp", "q": "Por que uma prensa hidráulica consegue multiplicar uma força?", "o": ["Porque a pressão é igual nos dois êmbolos e o êmbolo maior tem mais área.", "Porque o líquido cria energia.", "Porque o êmbolo maior é mais pesado.", "Porque a pressão é maior no êmbolo maior."], "a": 0, "h": "Com p igual, F = p · A.", "e": "Com a mesma pressão, a força é proporcional à área. No êmbolo maior, a força é maior.", "f": "prensa", "x": {"1": "Não há criação de energia.", "2": "O peso do êmbolo não é o que multiplica a força.", "3": "A pressão é igual nos dois êmbolos."}, "n": 2}, {"id": "f065", "an": "prensa_desl", "t": "pp", "q": "Verdadeiro ou falso: uma prensa hidráulica ideal multiplica também a energia (o trabalho) realizada.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Pense no deslocamento do êmbolo menor.", "e": "A força é multiplicada, mas o êmbolo menor se desloca mais. O trabalho é o mesmo (em um sistema ideal).", "v": 1, "x": {"0": "O trabalho (energia) se conserva em uma prensa ideal: a força multiplica, mas o deslocamento diminui. A afirmação é falsa."}, "n": 1}, {"id": "f066", "an": "freio", "t": "pp", "q": "Qual destes equipamentos usa o princípio de Pascal?", "o": ["O freio hidráulico de um carro.", "O termômetro de mercúrio.", "A lâmpada incandescente.", "O barômetro de Torricelli."], "a": 0, "h": "Pense em transmitir força por meio de um líquido.", "e": "Nos freios hidráulicos, a pressão aplicada no pedal é transmitida pelo fluido até as rodas.", "x": {"1": "O termômetro de mercúrio usa a dilatação.", "2": "A lâmpada incandescente usa o efeito Joule.", "3": "O barômetro mede a pressão atmosférica."}, "n": 1}, {"id": "f067", "an": "liq_gas", "t": "pp", "q": "Por que as prensas hidráulicas usam líquidos, e não gases?", "o": ["Porque os líquidos são praticamente incompressíveis e transmitem bem a pressão.", "Porque os líquidos não têm massa.", "Porque os gases são mais pesados.", "Porque os gases nunca transmitem pressão."], "a": 0, "h": "Pense no que ocorre quando você comprime ar e quando comprime água.", "e": "O líquido quase não muda de volume, então a pressão se transmite de forma eficiente.", "x": {"1": "Os líquidos têm massa.", "2": "O peso dos gases não é o motivo.", "3": "Os gases transmitem pressão, mas se comprimem."}, "n": 2}, {"id": "f068", "an": "prensa_forca", "t": "pp", "q": "Se a força aplicada no êmbolo menor de uma prensa for dobrada, a força no êmbolo maior:", "o": ["Também dobra.", "Fica pela metade.", "Não muda.", "Quadruplica."], "a": 0, "h": "F₂ = F₁ · A₂ / A₁ é proporcional a F₁.", "e": "As áreas continuam as mesmas. Dobrando F₁, dobra F₂.", "x": {"1": "Se a força cai à metade, ela não dobra.", "2": "A força no maior depende da força no menor.", "3": "F₂ é proporcional a F₁: dobrar F₁ dobra F₂, e não quadruplica."}, "n": 2}, {"id": "f069", "t": "pp", "q": "O êmbolo maior de uma prensa tem área 10 vezes a do êmbolo menor. A força no êmbolo maior é:", "o": ["10 vezes a força no menor.", "10 vezes menor.", "Igual.", "100 vezes maior."], "a": 0, "h": "F₂ / F₁ = A₂ / A₁.", "e": "F₂ = F₁ · (A₂ / A₁) = 10 F₁.", "x": {"1": "A prensa multiplica a força, não a divide.", "2": "Com áreas diferentes, as forças são diferentes.", "3": "A força multiplica na mesma proporção das áreas: 10 vezes."}, "an": "prensa_forca", "n": 2}, {"id": "f070", "an": "prensa_forca", "t": "pp", "q": "Em uma prensa hidráulica, as áreas dos êmbolos são 0,01 m² e 0,5 m². Uma força de 100 N no êmbolo menor equilibra qual força no maior?", "o": ["5000 N", "2 N", "50 N", "500 N"], "a": 0, "h": "F₂ = F₁ · A₂ / A₁.", "e": "F₂ = 100 × 0,5 / 0,01 = 5000 N.", "c": 1, "x": {"1": "2 N inverteu a razão das áreas.", "2": "50 N está dez vezes menor.", "3": "500 N está dez vezes menor."}, "n": 2}, {"id": "f071", "t": "pp", "q": "Um macaco hidráulico tem êmbolos de 2 cm² e 40 cm². Qual força mínima no êmbolo menor levanta um carro de peso 8000 N?", "o": ["400 N", "160 N", "4000 N", "8000 N"], "a": 0, "h": "F₁ = F₂ · A₁ / A₂.", "e": "F₁ = 8000 × 2 / 40 = 400 N.", "c": 1, "x": {"1": "160 N não vem de F₂ · A₁ / A₂.", "2": "4000 N dividiu 8000 por 2 apenas.", "3": "8000 N desconsidera a vantagem mecânica da prensa."}, "an": "prensa_forca", "n": 2}, {"id": "f072", "t": "pp", "q": "Em uma prensa, o êmbolo maior tem área 10 vezes a do menor. Se o êmbolo menor desce 20 cm, quanto sobe o maior?", "o": ["2 cm", "200 cm", "20 cm", "10 cm"], "a": 0, "h": "O volume de líquido que sai de um lado entra no outro.", "e": "A₁·d₁ = A₂·d₂, então d₂ = 20 / 10 = 2 cm.", "c": 1, "x": {"1": "200 cm inverte a relação dos deslocamentos.", "2": "20 cm seria igual, mas as áreas são diferentes.", "3": "10 cm é a razão das áreas, não o deslocamento."}, "an": "prensa_desl", "n": 3}, {"id": "f073", "an": "unid_dens", "t": "de", "q": "Verdadeiro ou falso: a massa específica da água é de aproximadamente 1 g/cm³.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Lembre da conversão para 1000 kg/m³.", "e": "1 g/cm³ equivale a 1000 kg/m³, valor usado para a água.", "v": 1, "x": {"1": "A massa específica da água é cerca de 1 g/cm³ (1000 kg/m³). A afirmação é verdadeira."}, "n": 1}, {"id": "f074", "an": "dens_temp", "t": "de", "q": "O que acontece com a massa específica de um líquido quando ele é aquecido e se dilata (sem perder massa)?", "o": ["Ela diminui.", "Ela aumenta.", "Fica igual.", "Torna-se nula."], "a": 0, "h": "μ = m/V; o que mudou em V?", "e": "A massa fica igual e o volume aumenta, então a razão m/V diminui.", "x": {"1": "A massa fica igual e o volume aumenta, então a massa específica diminui.", "2": "Ela muda, porque o volume cresce.", "3": "Não vira zero: a massa não desaparece."}, "n": 2}, {"id": "f075", "an": "calc_f075", "t": "de", "q": "Um cubo maciço de aresta 10 cm tem massa de 2,7 kg. Qual é a massa específica do material, em g/cm³?", "o": ["2,7 g/cm³", "27 g/cm³", "0,27 g/cm³", "2700 g/cm³"], "a": 0, "h": "V = 10 × 10 × 10 cm³ e m = 2700 g.", "e": "V = 1000 cm³ e m = 2700 g, então μ = 2700 / 1000 = 2,7 g/cm³.", "c": 1, "x": {"1": "27 g/cm³ erra a casa decimal.", "2": "0,27 g/cm³ erra a casa decimal.", "3": "2700 g/cm³ confunde com a massa em gramas. Falta dividir por 1000 cm³."}, "n": 2}, {"id": "f076", "an": "esferas_dens", "t": "de", "q": "Duas esferas têm a mesma massa, mas a esfera A tem o dobro do volume da esfera B. Qual afirmação é correta?", "o": ["A massa específica de A é a metade da de B.", "A massa específica de A é o dobro da de B.", "As massas específicas são iguais.", "A esfera A é sempre mais pesada."], "a": 0, "h": "μ = m/V com V maior.", "e": "Com a mesma massa, o dobro do volume significa metade da razão m/V.", "x": {"1": "Com o dobro de volume e a mesma massa, a massa específica de A é a metade.", "2": "As massas específicas são diferentes.", "3": "As massas são iguais, então A não é mais pesada."}, "n": 2}, {"id": "f077", "t": "pr", "q": "Verdadeiro ou falso: a pressão no fundo de um recipiente com líquido em repouso depende da profundidade, da massa específica e da gravidade, e não da forma do recipiente.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Teorema de Stevin: p = p₀ + μ·g·h.", "e": "Só a altura da coluna de líquido, a massa específica e g entram no cálculo.", "v": 1, "f": "hidro", "x": {"1": "A pressão hidrostática é p = ρ·g·h, e não depende da forma do recipiente. A afirmação é verdadeira."}, "an": "profund", "n": 1}, {"id": "f078", "t": "pr", "q": "Em vasos comunicantes com um mesmo líquido em repouso, o que se observa?", "o": ["O líquido atinge o mesmo nível em todos os ramos.", "O líquido sobe mais no ramo mais largo.", "O líquido sobe mais no ramo mais estreito.", "O líquido fica mais alto no ramo mais inclinado."], "a": 0, "h": "Pontos na mesma horizontal têm a mesma pressão.", "e": "A pressão depende da altura da coluna, não da largura do ramo. Por isso o nível é o mesmo.", "x": {"1": "O nível é o mesmo, independentemente da largura.", "2": "O nível é o mesmo, independentemente da largura.", "3": "A inclinação do ramo não altera o nível."}, "an": "vasos", "n": 2}, {"id": "f079", "t": "pr", "q": "Qual é a pressão total no fundo do mar a 10 m de profundidade? (p atm = 1,0 × 10⁵ Pa, μ = 1000 kg/m³, g = 10 m/s²)", "o": ["2,0 × 10⁵ Pa", "1,0 × 10⁵ Pa", "1,0 × 10⁶ Pa", "1,1 × 10⁵ Pa"], "a": 0, "h": "p = p atm + μ·g·h.", "e": "p = 10⁵ + 1000 × 10 × 10 = 10⁵ + 10⁵ = 2,0 × 10⁵ Pa.", "c": 1, "x": {"1": "1,0 × 10⁵ Pa ignora a pressão da coluna de água.", "2": "1,0 × 10⁶ Pa tem uma ordem de grandeza a mais.", "3": "1,1 × 10⁵ Pa esquece de multiplicar corretamente: ρgh = 10⁵ Pa."}, "an": "profund", "n": 2}, {"id": "f080", "t": "pr", "q": "Um mergulhador desce de 2 m para 6 m de profundidade. A pressão sobre ele:", "o": ["Aumenta.", "Diminui.", "Fica igual.", "Fica nula."], "a": 0, "h": "A pressão cresce com a profundidade.", "e": "Pelo teorema de Stevin, quanto maior a profundidade, maior a pressão.", "x": {"1": "A pressão cresce com a profundidade.", "2": "A profundidade mudou, então a pressão muda.", "3": "A pressão não é nula na água."}, "an": "profund", "n": 1}, {"id": "f081", "an": "ebulicao_p", "t": "pa", "q": "Verdadeiro ou falso: em cidades de grande altitude, a água ferve a uma temperatura menor que ao nível do mar.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Pressão menor, ponto de ebulição menor.", "e": "Em altitudes maiores a pressão atmosférica é menor, e a água ferve a uma temperatura mais baixa.", "v": 1, "x": {"1": "Com menor pressão atmosférica, a água ferve a temperatura menor. A afirmação é verdadeira."}, "n": 1}, {"id": "f082", "an": "barometro", "t": "pa", "q": "O barômetro é um instrumento usado para medir:", "o": ["A pressão atmosférica.", "A temperatura do ar.", "A umidade do ar.", "A velocidade do vento."], "a": 0, "h": "O de Torricelli usa mercúrio.", "e": "O barômetro mede a pressão atmosférica, como o de mercúrio de Torricelli.", "x": {"1": "A temperatura é medida com termômetro.", "2": "A umidade é medida com higrômetro.", "3": "O vento é medido com anemômetro."}, "n": 1}, {"id": "f083", "t": "pa", "q": "Ao puxar o êmbolo de uma seringa com a ponta mergulhada em um líquido, o líquido entra na seringa porque:", "o": ["A pressão dentro da seringa diminui e a pressão externa empurra o líquido.", "O êmbolo atrai o líquido por magnetismo.", "O líquido é mais leve que o ar.", "A seringa produz líquido."], "a": 0, "h": "Semelhante ao canudo.", "e": "Ao puxar o êmbolo, a pressão interna diminui. A pressão atmosférica sobre o líquido o empurra para dentro.", "x": {"1": "Não há magnetismo.", "2": "Não é o peso do líquido que explica a entrada na seringa.", "3": "A seringa não produz líquido."}, "an": "seringa", "n": 3}, {"id": "f084", "t": "pa", "q": "Em qual destes lugares a pressão do ar é menor?", "o": ["No topo do Everest.", "Em Santos, ao nível do mar.", "No fundo de uma mina.", "Em uma praia."], "a": 0, "h": "Menos ar acima, menos pressão.", "e": "No alto de uma montanha muito elevada, a coluna de ar acima é pequena e a pressão é a menor das opções.", "x": {"1": "Ao nível do mar a pressão é maior.", "2": "No fundo de uma mina a pressão é maior.", "3": "Na praia a pressão é maior que no alto do Everest."}, "an": "atmosfera", "n": 1}, {"id": "f085", "t": "to", "q": "O que acontece com a coluna de mercúrio se um pouco de ar entrar no espaço do topo do tubo de Torricelli?", "o": ["A coluna diminui.", "A coluna aumenta.", "Não muda.", "O mercúrio some."], "a": 0, "h": "O ar passa a exercer pressão sobre o mercúrio por cima.", "e": "O ar no topo empurra o mercúrio para baixo, então a altura da coluna diminui.", "f": "torricelli", "x": {"1": "O ar empurra o mercúrio para baixo, então a coluna diminui.", "2": "A coluna não pode aumentar.", "3": "O ar no topo exerce pressão e reduz a coluna."}, "an": "torr_ar", "n": 3}, {"id": "f086", "an": "calc_f086", "t": "to", "q": "Uma pressão de 380 mmHg corresponde a quantas atmosferas?", "o": ["0,5 atm", "2 atm", "3,8 atm", "0,38 atm"], "a": 0, "h": "1 atm = 760 mmHg.", "e": "380 / 760 = 0,5 atm.", "c": 1, "x": {"1": "2 atm inverteu a razão.", "2": "3,8 atm divide por 100 em vez de 760.", "3": "0,38 atm divide por 1000 em vez de 760."}, "n": 2}, {"id": "f087", "t": "to", "q": "Verdadeiro ou falso: se o experimento de Torricelli for feito em um local com pressão atmosférica maior, a coluna de mercúrio fica mais alta.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "A coluna equilibra a pressão atmosférica.", "e": "Maior pressão atmosférica sustenta uma coluna maior de mercúrio.", "v": 1, "x": {"1": "Quanto maior a pressão atmosférica, mais alta a coluna. A afirmação é verdadeira."}, "an": "torr_alt", "n": 1}, {"id": "f088", "an": "torr_76", "t": "to", "q": "Qual é a pressão, em mmHg, exercida pela coluna de 76 cm de mercúrio do experimento de Torricelli?", "o": ["760 mmHg", "76 mmHg", "7600 mmHg", "7,6 mmHg"], "a": 0, "h": "Converta cm para mm.", "e": "76 cm = 760 mm, então a pressão é 760 mmHg.", "c": 1, "x": {"1": "76 mmHg confundiu cm com mm.", "2": "7600 mmHg tem fator 10 a mais.", "3": "7,6 mmHg tem fator 100 a menos."}, "n": 2}, {"id": "f089", "an": "calc_f089", "t": "de", "q": "Um bloco tem massa de 600 g e volume de 200 cm³. Qual é a densidade?", "o": ["0,33 g/cm³", "3 g/cm³", "30 g/cm³", "120 000 g/cm³"], "a": 1, "h": "d = m/V.", "e": "d = 600/200 = 3 g/cm³.", "c": 1, "x": {"0": "0,33 g/cm³ inverteu a divisão.", "2": "30 g/cm³ erra por um fator 10.", "3": "120 000 g/cm³ multiplicou em vez de dividir."}, "n": 1}, {"id": "f090", "an": "unid_dens", "t": "de", "q": "A densidade da água é 1 g/cm³. Em kg/m³, esse valor é:", "o": ["1 kg/m³", "10 kg/m³", "100 kg/m³", "1 000 kg/m³"], "a": 3, "h": "1 m³ = 1 000 000 cm³ e 1 kg = 1 000 g.", "e": "1 g/cm³ = 10⁻³ kg / 10⁻⁶ m³ = 1 000 kg/m³.", "c": 1, "x": {"0": "1 kg/m³ não aplica o fator 1000.", "1": "10 kg/m³ erra duas ordens de grandeza.", "2": "100 kg/m³ erra uma ordem de grandeza."}, "n": 1}, {"id": "f091", "an": "calc_f091", "t": "de", "q": "Um cubo de aresta 10 cm tem massa de 2 kg. Qual é a densidade em kg/m³?", "o": ["200", "2 000", "20", "20 000"], "a": 1, "h": "Converta a aresta para metros: V = a³.", "e": "V = (0,1 m)³ = 10⁻³ m³. d = 2/10⁻³ = 2 000 kg/m³.", "c": 1, "x": {"0": "200 está dez vezes menor.", "2": "20 está cem vezes menor.", "3": "20 000 está dez vezes maior."}, "n": 2}, {"id": "f092", "an": "calc_f092", "t": "pr", "q": "Uma força de 300 N age perpendicularmente sobre uma área de 0,6 m². Qual é a pressão?", "o": ["180 Pa", "500 Pa", "50 Pa", "0,002 Pa"], "a": 1, "h": "p = F / A.", "e": "p = 300/0,6 = 500 Pa.", "c": 1, "x": {"0": "180 Pa é F × A, e a pressão é F ÷ A.", "2": "50 Pa está dez vezes menor.", "3": "0,002 Pa vem de inverter a divisão (A ÷ F)."}, "n": 1}, {"id": "f093", "an": "faca_area", "t": "pr", "q": "Por que uma faca bem afiada corta melhor que uma sem fio, com a mesma força?", "o": ["A área de contato menor gera pressão maior.", "A área menor gera pressão menor.", "A faca afiada tem mais massa.", "A força muda com o fio."], "a": 0, "h": "p = F / A.", "e": "Com a mesma força, quanto menor a área, maior a pressão sobre o material.", "x": {"1": "Área menor gera pressão maior.", "2": "A massa da faca não é o motivo.", "3": "A força é a mesma, apenas a área muda."}, "n": 1}, {"id": "f094", "an": "calc_f094", "t": "pr", "q": "Qual é a pressão da coluna de água a 5 m de profundidade? (ρ = 1 000 kg/m³, g = 10 m/s²; ignore a atmosfera)", "o": ["5 × 10³ Pa", "5 × 10⁴ Pa", "5 × 10⁵ Pa", "5 × 10² Pa"], "a": 1, "h": "p = ρ · g · h.", "e": "p = 1 000 · 10 · 5 = 5 × 10⁴ Pa.", "c": 1, "x": {"0": "5 × 10³ está uma ordem de grandeza menor.", "2": "5 × 10⁵ está uma ordem de grandeza maior.", "3": "5 × 10² está duas ordens de grandeza menor."}, "n": 2}, {"id": "f095", "t": "pr", "q": "Qual é a pressão total a 10 m de profundidade na água? (patm = 10⁵ Pa, ρ = 1 000 kg/m³, g = 10 m/s²)", "o": ["10⁵ Pa", "2 × 10⁵ Pa", "10⁶ Pa", "1,1 × 10⁵ Pa"], "a": 1, "h": "Some a atmosfera à pressão da coluna.", "e": "p = patm + ρgh = 10⁵ + 1 000·10·10 = 2 × 10⁵ Pa.", "c": 1, "x": {"0": "10⁵ Pa ignora a coluna de água.", "2": "10⁶ Pa tem uma ordem de grandeza a mais.", "3": "1,1 × 10⁵ Pa erra a pressão da coluna, que é 10⁵ Pa."}, "an": "profund", "n": 2}, {"id": "f096", "t": "pa", "q": "O que acontece com a pressão atmosférica quando se sobe uma montanha?", "o": ["Diminui, pois há menos ar acima.", "Aumenta.", "Não muda.", "Fica igual a zero logo no início."], "a": 0, "h": "Menos ar acima, menos peso.", "e": "Com a altitude, a camada de ar acima diminui e a pressão atmosférica também.", "x": {"1": "A pressão diminui com a altitude.", "2": "Ela varia com a altitude.", "3": "Ela diminui, mas não vira zero logo no início."}, "an": "atmosfera", "n": 1}, {"id": "f097", "an": "atm_peso", "t": "pa", "q": "A pressão atmosférica normal ao nível do mar vale aproximadamente:", "o": ["1,0 × 10³ Pa", "1,0 × 10⁵ Pa", "1,0 × 10⁷ Pa", "1,0 × 10 Pa"], "a": 1, "h": "1 atm = 760 mmHg.", "e": "1 atm ≈ 1,01 × 10⁵ Pa, ou cerca de 10⁵ Pa.", "x": {"0": "1,0 × 10³ Pa é cem vezes menor.", "2": "1,0 × 10⁷ Pa é cem vezes maior.", "3": "1,0 × 10 Pa é muito pequeno."}, "n": 1}, {"id": "f098", "an": "torr_exp", "t": "to", "q": "No experimento de Torricelli, o que existe no espaço acima do mercúrio dentro do tubo?", "o": ["Praticamente vácuo.", "Ar à pressão atmosférica.", "Água.", "Mais mercúrio."], "a": 0, "h": "A coluna fica sustentada pela pressão externa.", "e": "A coluna desce até equilibrar a pressão atmosférica, deixando acima dela um vácuo (vapor de mercúrio em quantidade desprezível).", "x": {"1": "Se houvesse ar à pressão atmosférica, a coluna não se manteria.", "2": "O tubo contém mercúrio, não água.", "3": "O espaço acima da coluna é vazio, não tem mais mercúrio."}, "n": 1}, {"id": "f099", "t": "to", "q": "No experimento de Torricelli, se o tubo for inclinado, a altura vertical da coluna de mercúrio:", "o": ["Não muda.", "Aumenta.", "Diminui.", "Vira zero."], "a": 0, "h": "A pressão depende da altura vertical.", "e": "A pressão depende da altura vertical. O comprimento da coluna no tubo aumenta, mas a altura vertical continua a mesma.", "x": {"1": "O comprimento da coluna no tubo aumenta, mas a altura vertical não.", "2": "A altura vertical não diminui.", "3": "A altura não vira zero."}, "an": "torr_incl", "n": 2}, {"id": "f100", "t": "cs", "q": "A lei de Stevin relaciona a pressão em um líquido com:", "o": ["A profundidade (p = p₀ + ρgh).", "A cor do líquido.", "O formato do recipiente.", "A temperatura apenas."], "a": 0, "h": "Simon Stevin estudou a pressão hidrostática.", "e": "A lei de Stevin diz que a pressão cresce com a profundidade: p = p₀ + ρ·g·h.", "x": {"1": "A cor não tem relação.", "2": "A pressão não depende do formato do recipiente.", "3": "A pressão depende da profundidade, da densidade e da gravidade."}, "an": "profund", "n": 1}, {"id": "f101", "t": "em", "q": "Um corpo de 2 L está totalmente imerso na água. Qual é o empuxo? (ρ = 1 000 kg/m³, g = 10 m/s²)", "o": ["2 N", "20 N", "200 N", "0,2 N"], "a": 1, "h": "E = ρ · V · g, com V em m³.", "e": "V = 2 L = 2 × 10⁻³ m³. E = 1 000 · 2 × 10⁻³ · 10 = 20 N.", "c": 1, "x": {"0": "2 N tem fator 10 a menos: V = 2 × 10⁻³ m³.", "2": "200 N tem fator 10 a mais.", "3": "0,2 N tem fator 100 a menos."}, "an": "empuxo", "n": 2}, {"id": "f102", "an": "afunda_flutua", "t": "em", "q": "Um corpo flutua em equilíbrio num líquido quando:", "o": ["Sua densidade é menor que a do líquido.", "Sua densidade é maior que a do líquido.", "Sua massa é maior que a do líquido.", "Seu volume é nulo."], "a": 0, "h": "Compare as densidades.", "e": "Se a densidade do corpo é menor que a do líquido, o empuxo máximo supera o peso e o corpo flutua.", "x": {"1": "Com densidade maior, o corpo afundaria.", "2": "A massa total do corpo não decide.", "3": "Volume nulo não existe."}, "n": 1}, {"id": "f103", "t": "em", "q": "Um bloco de madeira de densidade 800 kg/m³ flutua na água (1 000 kg/m³). Que fração do volume fica submersa?", "o": ["20%", "80%", "100%", "125%"], "a": 1, "h": "No equilíbrio, E = P.", "e": "ρ_água · V_sub · g = ρ_madeira · V · g. Então V_sub/V = 800/1 000 = 0,8 = 80%.", "c": 1, "x": {"0": "20% é a fração fora da água.", "2": "100% é o caso de densidade igual ao da água.", "3": "125% é impossível para um corpo flutuando."}, "an": "flut80", "n": 3}, {"id": "f104", "t": "pp", "q": "Numa prensa hidráulica, A₁ = 10 cm², A₂ = 200 cm² e F₁ = 50 N. Qual é F₂?", "o": ["500 N", "1 000 N", "2 500 N", "250 N"], "a": 1, "h": "F₁ / A₁ = F₂ / A₂.", "e": "F₂ = F₁ · A₂ / A₁ = 50 · 200/10 = 1 000 N.", "c": 1, "x": {"0": "500 N está dividido por 2.", "2": "2 500 N multiplicou por 50.", "3": "250 N está dividido por 4."}, "an": "prensa_forca", "n": 2}, {"id": "f105", "t": "pp", "q": "Numa prensa hidráulica ideal, o êmbolo menor, comparado ao maior:", "o": ["Percorre uma distância maior.", "Percorre uma distância menor.", "Percorre a mesma distância.", "Não se move."], "a": 0, "h": "O volume de líquido deslocado é o mesmo.", "e": "O volume deslocado é igual nos dois lados (A₁d₁ = A₂d₂). Com A₁ menor, o deslocamento d₁ é maior.", "x": {"1": "O deslocamento do menor é maior (A₁d₁ = A₂d₂).", "2": "As áreas são diferentes, então os deslocamentos também.", "3": "O êmbolo menor se move, e muito."}, "an": "prensa_desl", "n": 1}, {"id": "f106", "t": "pr", "q": "Qual é a pressão total a 20 m de profundidade na água? (p atm = 1,0 × 10⁵ Pa; μ = 1 000 kg/m³; g = 10 m/s²)", "o": ["3,0 × 10⁵ Pa", "2,0 × 10⁵ Pa", "2,0 × 10⁶ Pa", "1,2 × 10⁵ Pa"], "a": 0, "h": "Pressão total = atmosférica + μ·g·h.", "e": "μ·g·h = 1 000 · 10 · 20 = 2×10⁵ Pa. p = 1×10⁵ + 2×10⁵ = 3×10⁵ Pa.", "c": 1, "n": 2, "x": {"1": "2,0×10⁵ Pa é só a pressão da água; falta somar a atmosférica.", "2": "2,0×10⁶ Pa erra uma potência de dez em μ·g·h.", "3": "1,2×10⁵ Pa usa h = 2 m em vez de 20 m."}, "an": "calc_f106"}, {"id": "f107", "t": "pr", "q": "Em um tanque há 0,3 m de água (1 000 kg/m³) no fundo e, sobre ela, 0,5 m de óleo (800 kg/m³). Qual é a pressão (sem contar a atmosfera) no fundo do tanque? (g = 10 m/s²)", "o": ["8 000 Pa", "7 000 Pa", "3 000 Pa", "4 000 Pa"], "a": 1, "h": "Some a pressão de cada camada: p = μ₁·g·h₁ + μ₂·g·h₂.", "e": "Óleo: 800 · 10 · 0,5 = 4 000 Pa. Água: 1 000 · 10 · 0,3 = 3 000 Pa. Total: 7 000 Pa.", "c": 1, "n": 3, "x": {"0": "8 000 Pa trata os 0,8 m como se fossem só de água.", "2": "3 000 Pa considera só a água e esquece o óleo.", "3": "4 000 Pa considera só o óleo e esquece a água."}, "an": "calc_f107"}, {"id": "f108", "t": "em", "q": "Um bloco de 8 kg e volume 0,01 m³ é totalmente mergulhado na água (1 000 kg/m³) e solto. Com g = 10 m/s², qual é a força resultante sobre ele?", "o": ["20 N para baixo: o bloco afunda", "100 N para cima: o bloco sobe", "20 N para cima: o bloco sobe", "80 N para baixo: o bloco afunda"], "a": 2, "h": "Compare o empuxo μ·g·V com o peso m·g.", "e": "Empuxo: 1 000 · 10 · 0,01 = 100 N. Peso: 8 · 10 = 80 N. Resultante: 100 − 80 = 20 N para cima.", "c": 1, "n": 3, "x": {"0": "O empuxo (100 N) é maior que o peso (80 N), então a resultante é para cima.", "1": "100 N é só o empuxo; falta descontar o peso.", "3": "80 N é só o peso; falta considerar o empuxo."}, "an": "calc_f108"}, {"id": "f109", "t": "pp", "q": "Em uma prensa hidráulica, os êmbolos têm áreas de 20 cm² e 400 cm². Para o êmbolo maior subir 2 cm, de quanto o menor precisa descer?", "o": ["2 cm", "20 cm", "0,1 cm", "40 cm"], "a": 3, "h": "O volume que sai de um lado é o que entra no outro: A₁·d₁ = A₂·d₂.", "e": "20 · d₁ = 400 · 2 → d₁ = 800/20 = 40 cm.", "c": 1, "n": 3, "x": {"0": "Os deslocamentos não são iguais: o líquido deslocado é o mesmo volume.", "1": "20 cm é a razão das áreas, mas falta multiplicar pelos 2 cm do êmbolo maior.", "2": "0,1 cm divide em vez de multiplicar pela razão das áreas."}, "an": "calc_f109"}, {"id": "f113", "t": "pp", "q": "Um elevador hidráulico ergue um carro de 1 200 kg sobre um êmbolo de 0,3 m². O êmbolo menor tem 0,01 m². Qual é a força mínima aplicada nele? (g = 10 m/s²)", "o": ["400 N", "12 000 N", "36 N", "4 000 N"], "a": 0, "h": "F₁ / A₁ = F₂ / A₂, e F₂ é o peso do carro.", "e": "F₂ = 1 200 · 10 = 12 000 N. F₁ = F₂ · A₁ / A₂ = 12 000 · 0,01/0,3 = 400 N.", "c": 1, "n": 3, "x": {"1": "12 000 N é o peso do carro, sem aproveitar a vantagem da prensa.", "2": "36 N multiplica pela razão das áreas em vez de dividir.", "3": "4 000 N erra a razão das áreas (usou 3 em vez de 30)."}, "an": "calc_f113"}, {"id": "f110", "t": "de", "q": "Misturam-se 200 g de água (1,0 g/cm³) e 300 g de álcool (0,8 g/cm³), sem variação de volume. Qual é, aproximadamente, a densidade da mistura?", "o": ["0,90 g/cm³", "0,87 g/cm³", "0,80 g/cm³", "1,10 g/cm³"], "a": 1, "h": "Densidade da mistura = massa total / volume total.", "e": "Volume da água: 200 cm³. Volume do álcool: 300/0,8 = 375 cm³. d = 500/575 ≈ 0,87 g/cm³.", "c": 1, "n": 3, "x": {"0": "0,90 g/cm³ é a média simples das densidades; as massas e volumes são diferentes.", "2": "0,80 g/cm³ é a densidade do álcool, ignorando a água.", "3": "1,10 g/cm³ é maior que as duas densidades: impossível para uma mistura."}, "an": "calc_f110"}, {"id": "f111", "t": "em", "q": "Um bloco de madeira de densidade 600 kg/m³ e volume 0,005 m³ flutua na água (1 000 kg/m³). Qual é o volume submerso?", "o": ["5,0 × 10⁻³ m³", "2,0 × 10⁻³ m³", "3,0 × 10⁻³ m³", "6,0 × 10⁻³ m³"], "a": 2, "h": "Ao flutuar, o empuxo é igual ao peso.", "e": "Peso = 600 · 10 · 0,005 = 30 N. Empuxo = 1 000 · 10 · V = 30 → V = 3×10⁻³ m³ (60% do bloco).", "c": 1, "n": 3, "x": {"0": "5,0×10⁻³ m³ é o volume total: o bloco não afunda por inteiro ao flutuar.", "1": "2,0×10⁻³ m³ é a parte que fica fora da água.", "3": "6,0×10⁻³ m³ é maior que o volume do bloco: impossível."}, "an": "calc_f111"}, {"id": "f112", "t": "to", "q": "O experimento de Torricelli usa mercúrio (13 600 kg/m³) e a coluna tem 76 cm. Se fosse usado óleo (800 kg/m³) no lugar, qual seria, aproximadamente, a altura da coluna? (g = 10 m/s²)", "o": ["≈ 10,3 m", "≈ 1,3 m", "≈ 129 m", "≈ 12,9 m"], "a": 3, "h": "A pressão atmosférica é a mesma: μ₁·g·h₁ = μ₂·g·h₂.", "e": "p = 13 600 · 10 · 0,76 ≈ 1,03×10⁵ Pa. h = p / (800·10) ≈ 12,9 m.", "c": 1, "n": 3, "x": {"0": "10,3 m é a altura que seria obtida com água (1 000 kg/m³), não com óleo.", "1": "1,3 m está dez vezes menor: confira as potências de dez.", "2": "129 m está dez vezes maior: confira as potências de dez."}, "an": "calc_f112"}, {"id": "f114", "t": "pr", "q": "Uma pessoa de 70 kg se apoia em um só pé, cuja área de apoio é 200 cm². Qual é a pressão exercida no chão? (g = 10 m/s²)", "o": ["3,5 × 10⁴ Pa", "1,75 × 10⁴ Pa", "3,5 × 10⁶ Pa", "7 × 10² Pa"], "a": 0, "h": "Converta a área para m² (1 m² = 10 000 cm²) e use p = F / A.", "e": "F = 70 · 10 = 700 N. A = 200 cm² = 0,02 m². p = 700/0,02 = 35 000 Pa.", "c": 1, "n": 2, "x": {"1": "1,75×10⁴ Pa seria com os dois pés apoiados.", "2": "3,5×10⁶ Pa vem de usar 200 cm² sem converter para m².", "3": "7×10² Pa é o peso em newtons, sem dividir pela área."}, "an": "calc_f114"}, {"id": "f115", "t": "pr", "q": "Uma janela de vidro de 0,05 m² está a 30 m de profundidade na água. Qual é a força total sobre ela? (p atm = 1,0 × 10⁵ Pa; μ = 1 000 kg/m³; g = 10 m/s²)", "o": ["1,5 × 10⁴ N", "2,0 × 10⁴ N", "4,0 × 10⁵ N", "3,0 × 10⁵ N"], "a": 1, "h": "Primeiro a pressão total; depois F = p·A.", "e": "p = 1×10⁵ + 1 000·10·30 = 4×10⁵ Pa. F = p·A = 4×10⁵ · 0,05 = 2×10⁴ N.", "c": 1, "n": 3, "x": {"0": "1,5×10⁴ N usa só a pressão da água; falta a atmosférica.", "2": "4,0×10⁵ é a pressão em pascal, sem multiplicar pela área.", "3": "3,0×10⁵ é a pressão da água em pascal, sem somar a atmosférica nem multiplicar pela área."}, "an": "calc_f115"}, {"id": "f116", "t": "em", "q": "Um bloco de 2 kg, pendurado em um dinamômetro e totalmente mergulhado na água (1 000 kg/m³), indica 12 N. Qual é o volume do bloco? (g = 10 m/s²)", "o": ["2 × 10⁻³ m³", "1,2 × 10⁻³ m³", "8 × 10⁻⁴ m³", "8 × 10⁻³ m³"], "a": 2, "h": "O dinamômetro indica o peso aparente: P − E.", "e": "Peso = 2·10 = 20 N. Empuxo = 20 − 12 = 8 N. V = E / (μ·g) = 8/(1 000·10) = 8×10⁻⁴ m³.", "c": 1, "n": 3, "x": {"0": "2×10⁻³ m³ usa o peso (20 N) como se fosse o empuxo.", "1": "1,2×10⁻³ m³ usa a leitura do dinamômetro (12 N) como empuxo.", "3": "8×10⁻³ m³ está dez vezes maior: confira as potências de dez."}, "an": "calc_f116"}, {"id": "f117", "t": "pr", "q": "Em um tubo em U aberto há água (1 000 kg/m³) em um ramo e óleo (800 kg/m³) no outro, em equilíbrio. A coluna de óleo, acima da superfície de separação, tem 20 cm. Qual é a altura da coluna de água acima desse mesmo nível?", "o": ["25 cm", "20 cm", "12,8 cm", "16 cm"], "a": 3, "h": "No mesmo nível, as pressões nos dois ramos são iguais: μ₁·h₁ = μ₂·h₂.", "e": "1 000 · h = 800 · 20 → h = 16 000/1 000 = 16 cm.", "c": 1, "n": 3, "x": {"0": "25 cm inverte a razão das densidades: a água é mais densa, então sua coluna é menor.", "1": "20 cm só vale se os líquidos tivessem a mesma densidade.", "2": "12,8 cm usa a razão das densidades elevada ao quadrado."}, "an": "calc_f117"}];
